var rows=new System.Collections.Generic.List<string>();foreach(var s in UnityEngine.Object.FindObjectsByType<UnityEngine.AudioSource>(UnityEngine.FindObjectsSortMode.None))if(s.clip)rows.Add(s.name+" loaded="+s.clip.loadState+" playing="+s.isPlaying+" samples="+s.timeSamples+" enabled="+s.enabled+" active="+s.gameObject.activeInHierarchy+" loop="+s.loop+" volume="+s.volume);return rows;
